-- Reviewed corrections from approved source records. Optimistic guards preserve concurrent staff edits.
-- Run once after customer_experience migration. Prior versions remain in ig_content_revisions.
begin;
do $release$
declare patch jsonb;c public.ig_content;
begin
 for patch in select value from jsonb_array_elements($patches$[{"id": "941565bb-9353-4396-a976-9d7a9cac7fd5", "version": 5, "title": "Park Plaza Ludhiana", "summary": "A 114-key city hotel on approximately 1.46 acres in Ludhiana, held by Majestic Hotels Limited and also identified as Majestic Park Plaza. Explore the asset through the applicable resolution process; current operating status and transaction terms require confirmation.", "body": "Park Plaza Ludhiana, also identified as Majestic Park Plaza in the supplied investor presentation, is one hotel asset held by Majestic Hotels Limited. It is located at Bhai Bala Chowk on Ferozepur Road, Ludhiana, Punjab. The source material reports 114 rooms on approximately 1.46 acres, with the land measurement to be reconciled against title and sanctioned records.\n\n## The hotel and its operating footprint\n\nThe supplied material describes guest accommodation, food and beverage outlets, banquet halls and meeting facilities. These support a city-hotel proposition serving corporate travel, events and social functions. The documented built form includes two basement levels, a ground floor and ten upper floors.\n\n## Room inventory and information period\n\nThe source presentation reports 77 operational rooms and 37 rooms requiring further review for refurbishment or possession matters, within the total inventory of 114. These are source-reported figures, not a confirmation of the hotel's current operating inventory.\n\nThe historical operating information includes monthly trading figures through October 2024. Current room availability, occupancy, revenue, possession and capital expenditure requirements must be confirmed before investment decisions.\n\n## Operator agreement\n\nThe supplied presentation reports a Sarovar Hotels management agreement through 31 December 2028. The executed agreement, continuing validity, transfer provisions and operating obligations require review. This is an operator agreement, not the tenure of the underlying property.\n\n## Transaction and next steps\n\nThe source material describes an investment through a resolution-plan process. The current process stage, eligibility, deadlines and approvals must be checked with the authorised parties. India Gully can coordinate the approved property information and the next disclosure step through the project data room.\n\nThe main diligence priorities are title and land measurement, possession and room recovery, current operational information, refurbishment requirements, and the applicable management and transaction documents.", "remove": ["tenure"], "data": {"asset_class": "City hotel", "transaction_type": "Corporate insolvency resolution", "image_alt": "Park Plaza Ludhiana hotel", "management_agreement": "Sarovar Hotels agreement reported through 31 December 2028; current validity and terms to be confirmed", "reference": "Majestic Hotels Limited · Park Plaza Ludhiana", "data_as_of": "Historical operating material includes trading figures through October 2024; current operations require confirmation", "last_verified_at": "2026-11-18", "process_stage": "Resolution-plan route described in the source; current stage and deadlines to be confirmed", "availability": "Current status and room inventory to be confirmed"}}, {"id": "e99704fa-dcb6-4cb8-8ba0-85c34363f653", "version": 4, "title": "Unitech Cyber Park Office, Gurugram", "summary": "A fitted 4,361 sq ft office in Tower B, Unitech Cyber Park, Sector 39, Gurugram. The supplied layout includes 70 workstations, two cabins, meeting and conference rooms, a pantry, reception and server room. Confirm the rent period, area basis and current availability before proceeding.", "body": "This office mandate covers Unit 801 on the eighth floor of Tower B, Unitech Cyber Park, Sector 39, Gurugram, Haryana. The supplied schedule records 4,361 sq ft; the carpet or chargeable area basis remains to be confirmed.\n\n## Layout and fit-out\n\nThe supplied layout includes 70 workstations, two cabins, a meeting room, a conference room, pantry, reception and server room. The approved handover description is fully fitted out. Inspect the premises and confirm the included fixtures before agreeing the handover terms.\n\n## Commercial terms to confirm\n\nThe approved indicative rent is ₹100 per sq ft. The billing period, chargeable area basis, common area maintenance, applicable taxes, deposit, escalation and possession date have not been confirmed in this public brief. Request the complete commercial schedule before comparing this quote with another offer.\n\n## Review the space\n\nExplore the approved drawing and unit schedule below. India Gully can confirm current availability, arrange the next discussion and coordinate access to additional authorised information.", "data": {"formats": "Office", "floors": "Eighth floor", "area_range": "4,361 sq ft; area basis to confirm", "rent_period": "To confirm", "area_basis": "To confirm: carpet / chargeable area", "cam": "To confirm", "taxes": "To confirm", "possession": "To confirm", "permitted_use": "Office use described in the source; permitted use and approvals to be verified", "image_alt": "Unitech Cyber Park, Gurugram", "last_verified_at": "2026-11-18", "data_as_of": "Supplied office layout and approved commercial label reviewed; current availability requires confirmation", "units": [{"unit": "801", "floor": "8", "area": "4,361 sq ft", "basis": "To confirm", "zone": "Office", "status": "To confirm"}], "plans": [{"path": "e99704fa-dcb6-4cb8-8ba0-85c34363f653/ae9b44e1-1f93-4f15-9d90-5914ef619bc4.jpg", "type": "Floor drawing", "label": "Eighth floor layout"}]}}, {"id": "9a9c6e6b-826b-4af4-8208-641e1a1bad15", "version": 7, "title": "Alphathum Offices, Noida", "data": {"sector": "Commercial", "asset_class": "Office", "transaction_type": "Sale", "image_alt": "Bhutani Alphathum office development, Sector 90, Noida"}}, {"id": "3673f2e1-d926-49ae-b244-06c6eba9a0dd", "version": 5, "title": "Jaisalkot Heritage Resort, Jaisalmer", "data": {"sector": "Hospitality", "asset_class": "Heritage resort", "transaction_type": "Corporate insolvency resolution", "area_unit": "acres", "process_stage": "Resolution-plan route in the supplied brief; current stage and deadlines to be confirmed"}}, {"id": "77ff1711-a791-408b-a6aa-b656bd25839b", "version": 7, "title": "Shirdi Hotel Development & Residential Plots", "data": {"sector": "Mixed use", "asset_class": "Hotel development and residential land", "transaction_type": "Corporate insolvency resolution", "process_stage": "Corporate insolvency resolution described in the supplied brief; current status to be confirmed"}}, {"id": "bd951a25-c684-4895-b99b-e963539ef91a", "version": 5, "data": {"dimensions": "Length 168.50 mm (manufacturer article ARIA140ARN112)", "material": "18/10 stainless steel range; confirm final sample specification", "finish": "To confirm with the manufacturer", "sample_policy": "Request a sample in your quotation; availability and charges to be confirmed", "specification_status": "Article and length checked against the Ariane cutlery catalogue; final sample and finish require confirmation"}, "body": "Manufacturer article ARIA140ARN112. Length: 168.50 mm. The manufacturer catalogue places this item in its 18/10 cutlery range. Box packing quantity: 12. Confirm the finish and final sample specification in the quotation."}]$patches$::jsonb) loop
  select * into c from public.ig_content where id=(patch->>'id')::uuid for update;
  if c.version is distinct from (patch->>'version')::integer or c.published_version is distinct from c.version then raise exception 'Content changed since review: %',c.id;end if;
  update public.ig_content set title=coalesce(patch->>'title',title),summary=coalesce(patch->>'summary',summary),body=coalesce(patch->>'body',body),
   seo_title=coalesce(patch->>'title',seo_title),seo_description=case when patch ? 'summary' then left(patch->>'summary',160) else seo_description end,
   public_data=(public_data-array(select jsonb_array_elements_text(coalesce(patch->'remove','[]'))))||coalesce(patch->'data','{}'),
   version=version+1,published_version=version+1,status='published',updated_at=now() where id=c.id returning * into c;
  insert into public.ig_content_revisions(content_id,version,snapshot,actor_id) values(c.id,c.version,to_jsonb(c),c.updated_by);
  update public.ig_public_content set title=c.title,summary=c.summary,body=c.body,seo_title=c.seo_title,seo_description=c.seo_description,public_data=c.public_data,version=c.version,published_at=now() where id=c.id;
  if not found then raise exception 'Published record missing: %',c.id;end if;
  insert into public.ig_audit(action,entity_id,detail) values('content.experience_review',c.id::text,jsonb_build_object('version',c.version,'scope','Canonical identity, classification and source-qualified public facts; availability not newly confirmed'));
 end loop;
end $release$;
commit;
